SELECT 
FROM sensitive_word
WHERE id = #{id}
  AND region = #{region}
LIMIT 1

SELECT COUNT(1)
FROM sensitive_word
WHERE region = #{region}
  AND LOWER(word) = LOWER(#{word})

    AND id != #{excludeId}

mapper.update:
UPDATE sensitive_word
SET enabled = #{enabled},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND region = #{region}

mapper.delete:
DELETE FROM sensitive_word
WHERE id = #{id}
  AND region = #{region}
